/* The cartridge tables in src/cartdb.c, generated by tools/cartdb.cmake from
   MAME's CC0 software lists (THIRD-PARTY-NOTICES.md). Every table is const
   and holds no pointer, so it lives in read-only data. Not installed. */
#ifndef MUHTARI_CARTDB_H
#define MUHTARI_CARTDB_H

#include <stdint.h>

/* One ROM chip of a 7800 list entry: the SHA-1 of its bytes, the entry it
   belongs to, and its part, the chip's place in the entry's slices (0 for a
   single-chip entry). Sorted by SHA-1, then by entry, so the first of two
   equal keys is the lower entry. */
struct muhtari__cartdb_key {
    uint8_t sha1[20];
    uint8_t entry;
    uint8_t part;
};

/* Entry flags. A list entry may run on both TV systems. An entry that is
   not a cartridge (the High Score Cartridge ROM, the XM and the XBoard) is
   kept so that an image matching it is refused as not a cartridge. */
enum {
    MUHTARI__CARTDB_NTSC = 1u,
    MUHTARI__CARTDB_PAL = 2u,
    MUHTARI__CARTDB_LIGHTGUN = 4u,
    MUHTARI__CARTDB_NOT_CART = 8u
};

/* One 7800 list entry, in the list's order. board, board_options and sound
   use the values the probe reports: board linear 1, SuperGame 2, Activision
   3, Absolute 4, Fractalus 5 (0 for an entry that is not a cartridge);
   board_options bit 0 ROM at $4000; sound bit 0 POKEY at $4000, bit 1 POKEY
   at $0450. ram_kib is the cartridge RAM in KiB. parts counts the keyed
   chips; layout is 1 + an index into the layouts when parts > 1, else 0. */
struct muhtari__cartdb_entry {
    uint16_t ram_kib;
    uint8_t board;
    uint8_t board_options;
    uint8_t sound;
    uint8_t flags;
    uint8_t parts;
    uint8_t layout;
};

/* The slices of a multi-chip image, in address order: size[i] bytes hold
   chip part[i]. A size of 0 ends the list. A part may repeat, where the
   board mirrors one chip twice. */
#define MUHTARI__CARTDB_SLICES_MAX 4
struct muhtari__cartdb_layout {
    uint32_t size[MUHTARI__CARTDB_SLICES_MAX];
    uint8_t part[MUHTARI__CARTDB_SLICES_MAX];
};

extern const struct muhtari__cartdb_key muhtari__cartdb_7800_keys[];
extern const uint32_t muhtari__cartdb_7800_key_count;
extern const struct muhtari__cartdb_entry muhtari__cartdb_7800_entries[];
extern const uint32_t muhtari__cartdb_7800_entry_count;
extern const struct muhtari__cartdb_layout muhtari__cartdb_7800_layouts[];
extern const uint32_t muhtari__cartdb_7800_layout_count;

/* The first 8 bytes of the SHA-1 of every 2600 list ROM, sorted and
   distinct. A match only refuses an image as a 2600 one. */
extern const uint8_t muhtari__cartdb_2600_prefix[][8];
extern const uint32_t muhtari__cartdb_2600_prefix_count;

#endif /* MUHTARI_CARTDB_H */
